Tutor.registerIndex("kor-univ", [
{"id":"kor-u-write-01","kind":"unit","title":"대학 글쓰기의 이해","text":"고등학교 글쓰기와 달리 대학의 학술적 글쓰기가 무엇을 요구하는지 알고, 주제 선정에서 퇴고까지 글쓰기 과정 전체를 살펴봅니다. 학술적 글쓰기의 특성인 객관성·논리성·근거를 설명할 수 있다. 출처 밝히기·용어 정의 등 학술 공동체의 글쓰기 관습을 알고 따를 수 있다. 주제 선정에서 퇴고까지 글쓰기 과정을 단계별로 계획할 수 있다. 객관적 어조와 명확한 문장…","keywords":["학술적 글쓰기","학술 공동체","객관성","논리성","근거","선행 연구","참고 문헌","초고","퇴고"],"ref":{"tab":"concepts","idx":0},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-01","grade":"u"},
{"id":"kor-u-write-01#c0","kind":"concept","title":"학술적 글쓰기란 무엇인가","text":"대학에서 쓰는 보고서·논문처럼 학문적 질문에 답하고, 그 답을 근거로 뒷받침하는 글을 쓰는 일을 학술적 글쓰기라고 합니다. 고등학교에서 흔히 써 온 글이 배운 내용을 정리하거나 생각과 느낌을 표현하는 데 무게를 두었다면, 학술적 글은 아직 답이 정해지지 않은 질문을 세우고, 자료와 추론","keywords":["학술적 글쓰기","학술 공동체","근거"],"ref":{"tab":"concepts","idx":0},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-01","grade":"u"},
{"id":"kor-u-write-01#c1","kind":"concept","title":"학술적 글의 특성: 객관성·논리성·근거","text":"학술적 글은 다음 세 가지 특성을 갖춥니다. 객관성: 개인의 감정이나 선호가 아니라 누구나 확인할 수 있는 사실과 자료에 기대어 서술합니다. 글쓴이의 주장도 \"확인 가능한 근거로 뒷받침되는 판단\"으로 제시합니다. 논리성: 주장과 근거, 문장과 문장, 단락과 단락이 빈틈없이 이어집니다. ","keywords":["객관성","논리성","근거"],"ref":{"tab":"concepts","idx":1},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-01","grade":"u"},
{"id":"kor-u-write-01#c2","kind":"concept","title":"학술 공동체의 글쓰기 관습","text":"학술 공동체는 서로의 글을 읽고 검토하며 지식을 쌓아 갑니다. 그 과정에서 굳어진 약속, 곧 글쓰기 관습이 있습니다. 출처 밝히기: 남의 생각·자료·표현을 쓰면 본문에 인용 표시를 하고, 글 끝에 참고 문헌을 답니다. 이를 어기면 표절이 됩니다. 선행 연구와 대화하기: 그 주제에 대해 ","keywords":["학술 공동체","선행 연구","참고 문헌"],"ref":{"tab":"concepts","idx":2},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-01","grade":"u"},
{"id":"kor-u-write-01#c3","kind":"concept","title":"글쓰기 과정: 주제 선정에서 퇴고까지","text":"학술적 글은 한 번에 완성되지 않습니다. 대체로 다음 과정을 거칩니다. 단계 · 하는 일 주제 선정 · 관심 있는 화제를 다룰 만한 범위로 좁히고, 답할 질문을 정한다 자료 조사 · 논문·책·통계를 찾아 읽고 출처와 함께 메모한다 개요 짜기 · 서론·본론·결론에 들어갈 내용과 순서를 정","keywords":["근거","초고","퇴고"],"ref":{"tab":"concepts","idx":3},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-01","grade":"u"},
{"id":"kor-u-write-01#c4","kind":"concept","title":"학술 문체: 객관적 어조와 명확한 문장","text":"학술적 글은 내용뿐 아니라 문체로도 신뢰를 얻습니다. 객관적 어조 감정·평가를 드러내는 말(놀랍게도, 한심한, 끔찍한) 대신 사실과 정도를 나타내는 말을 씁니다. 구어체·줄임말(근데, 좀, 넘, 딱) 대신 문어체를 쓰고, 서술은 \"-다\"로 끝나는 평서문으로 씁니다. 근거의 강도에 맞게 ","keywords":["근거"],"ref":{"tab":"concepts","idx":4},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-01","grade":"u"},
{"id":"kor-u-write-01#t0","kind":"term","title":"학술적 글쓰기","text":"학문적 질문에 답하고 그 답을 근거로 뒷받침하여 학술 공동체의 검토를 받는 글쓰기입니다. 보고서·논문이 대표적입니다.","keywords":["학술적 글쓰기"],"ref":{"tab":"terms","idx":0},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-01","grade":"u"},
{"id":"kor-u-write-01#t1","kind":"term","title":"학술 공동체","text":"같은 분야를 공부하고 연구하며 서로의 글을 읽고 검토하는 사람들의 모임입니다.","keywords":["학술 공동체"],"ref":{"tab":"terms","idx":1},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-01","grade":"u"},
{"id":"kor-u-write-01#t2","kind":"term","title":"객관성","text":"개인의 감정이나 선호가 아니라 누구나 확인할 수 있는 사실과 자료에 기대어 서술하는 성질입니다.","keywords":["객관성"],"ref":{"tab":"terms","idx":2},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-01","grade":"u"},
{"id":"kor-u-write-01#t3","kind":"term","title":"논리성","text":"주장과 근거, 문장과 문장, 단락과 단락이 비약 없이 이어지는 성질입니다.","keywords":["논리성"],"ref":{"tab":"terms","idx":3},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-01","grade":"u"},
{"id":"kor-u-write-01#t4","kind":"term","title":"근거","text":"주장을 뒷받침하는 자료나 이유입니다. 연구 결과·통계·사례·문헌 등이 있으며, 학술적 글에서는 출처를 함께 밝힙니다.","keywords":["근거"],"ref":{"tab":"terms","idx":4},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-01","grade":"u"},
{"id":"kor-u-write-01#t5","kind":"term","title":"선행 연구","text":"내가 다루는 주제에 대해 앞서 다른 연구자들이 수행하여 발표한 연구입니다.","keywords":["선행 연구"],"ref":{"tab":"terms","idx":5},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-01","grade":"u"},
{"id":"kor-u-write-01#t6","kind":"term","title":"참고 문헌","text":"글에서 인용하거나 참고한 자료를 정해진 양식에 따라 글 끝에 모아 적은 목록입니다.","keywords":["참고 문헌"],"ref":{"tab":"terms","idx":6},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-01","grade":"u"},
{"id":"kor-u-write-01#t7","kind":"term","title":"초고","text":"개요에 따라 처음으로 끝까지 써 낸 원고입니다. 퇴고를 거쳐 완성 원고가 됩니다.","keywords":["초고"],"ref":{"tab":"terms","idx":7},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-01","grade":"u"},
{"id":"kor-u-write-01#t8","kind":"term","title":"퇴고","text":"초고를 다시 읽으며 논지·구조·문장·표기를 고치는 일입니다. 큰 것(구조)에서 작은 것(맞춤법) 순서로 합니다.","keywords":["퇴고"],"ref":{"tab":"terms","idx":8},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-01","grade":"u"},
{"id":"kor-u-write-01#f0","kind":"faq","title":"학술적 글에서 \"나는\"이라고 써도 되나요?","text":"분야와 과제에 따라 다릅니다. 국내 학술적 글에서는 \"나는\" 대신 \"이 글은\", \"본고는\", \"필자는\" 같은 표현을 많이 씁니다. 영어권의 일부 분야처럼 일인칭을 허용하는 곳도 있으니 과제 안내나 교수자의 지침을 확인하십시오. 어느 쪽이든 중요한 것은 주어의 형태보다 감정이 아니라 근거로 판단하는 태도입니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-01","grade":"u"},
{"id":"kor-u-write-01#f1","kind":"faq","title":"객관적으로 쓰라는데, 그러면 제 주장은 어디에 쓰나요?","text":"객관성은 주장을 빼라는 뜻이 아닙니다. 학술적 글에는 오히려 분명한 주장(논지)이 있어야 합니다. 다만 \"나는 이렇게 느낀다\"가 아니라 \"이런 근거로 볼 때 이렇게 판단할 수 있다\"의 꼴로, 근거와 함께 제시합니다. 대개 서론에서 논지를 밝히고 본론에서 근거로 뒷받침합니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-01","grade":"u"},
{"id":"kor-u-write-01#f2","kind":"faq","title":"고등학교 때 쓴 논술과 대학 보고서는 무엇이 다른가요?","text":"논술은 대개 주어진 제시문과 정해진 시간 안에서 논리적으로 주장을 펴는 글입니다. 대학 보고서는 스스로 질문을 세우고, 직접 자료를 찾아 읽고, 그 출처를 밝히며, 여러 날에 걸쳐 고쳐 쓰는 글입니다. 논리적으로 주장을 편다는 점은 같지만, 자료 조사와 출처 표시, 글쓰기 과정 전체를 스스로 해낸다는 점이 다릅니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-01","grade":"u"},
{"id":"kor-u-write-01#m0","kind":"mistake","title":"자주 하는 실수","text":"객관성을 \"주장하지 않기\"로 오해해 자료만 나열하는 실수 — 자료는 주장을 뒷받침하려고 쓰는 것입니다. 무엇을 말하려는지(논지)를 분명히 밝힙니다.","keywords":[],"ref":{"tab":"faq"},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-01","grade":"u"},
{"id":"kor-u-write-01#m1","kind":"mistake","title":"자주 하는 실수","text":"\"정말\", \"엄청\", \"누구나\", \"반드시\"로 강조하면 설득력이 높아진다고 여기는 실수 — 학술적 글에서는 근거와 수치가 설득력을 만듭니다. 강조어는 오히려 신뢰를 떨어뜨립니다.","keywords":[],"ref":{"tab":"faq"},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-01","grade":"u"},
{"id":"kor-u-write-01#m2","kind":"mistake","title":"자주 하는 실수","text":"마감 직전에 한 번에 쓰고 퇴고를 건너뛰는 실수 — 단계마다 날짜를 정하고, 퇴고할 시간을 반드시 남겨 둡니다.","keywords":[],"ref":{"tab":"faq"},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-01","grade":"u"},
{"id":"kor-u-write-02","kind":"unit","title":"학술적 글 읽기","text":"논문과 학술서의 짜임을 알고, 핵심 논지와 개념어를 찾아 메모하며 비판적으로 읽는 법을 익힙니다. 학술 논문의 짜임(초록·서론·본론·결론·참고 문헌)을 알고 목적에 맞게 골라 읽을 수 있다. 연구 질문과 핵심 논지를 찾아 정리할 수 있다. 개념어의 정의를 파악하고 주석과 질문을 달며 읽을 수 있다. 글의 숨은 전제와 한계를 찾아 비판적으로 읽을 수 있다.","keywords":["초록","주제어","연구 질문","논지","조작적 정의","주석","서지 정보","전제","한계","비판적 독해"],"ref":{"tab":"concepts","idx":0},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-02","grade":"u"},
{"id":"kor-u-write-02#c0","kind":"concept","title":"학술 논문의 짜임","text":"학술 논문은 정해진 짜임을 따르므로, 짜임을 알면 필요한 정보를 빨리 찾을 수 있습니다. 부분 · 담는 내용 제목·초록 · 초록은 연구 목적·방법·주요 결과·결론을 짧게 간추린 글. 아래에 주제어(핵심 낱말)를 적는다 서론 · 연구 배경과 필요성, 선행 연구의 성과와 빈 곳, 연구 질문","keywords":["초록","주제어","연구 질문","서지 정보","한계"],"ref":{"tab":"concepts","idx":0},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-02","grade":"u"},
{"id":"kor-u-write-02#c1","kind":"concept","title":"연구 질문과 핵심 논지 찾기","text":"학술적 글을 읽을 때 가장 먼저 찾을 것은 두 가지입니다. 연구 질문: 이 글이 답하려는 물음입니다. 연구 문제, 연구 목적이라고도 합니다. 핵심 논지: 그 물음에 대한 글쓴이의 답, 곧 글 전체의 중심 주장입니다. 연구 질문은 대개 서론의 끝부분에 있습니다. \"이 글은 ~을 밝히고자 ","keywords":["연구 질문","논지"],"ref":{"tab":"concepts","idx":1},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-02","grade":"u"},
{"id":"kor-u-write-02#c2","kind":"concept","title":"개념어와 정의 파악하기","text":"학술적 글은 일상어도 특정한 뜻으로 정의해서 씁니다. 개념어의 정의를 놓치면 글 전체를 잘못 읽게 됩니다. 정의는 다음과 같은 표현으로 드러납니다. \"~(이)란 ~을 말한다\" \"이 글에서 ~은 ~을 가리킨다\" \"~을 ~(으)로 정의한다\" 특히 연구 논문에서는 추상적인 개념을 측정할 수 ","keywords":["조작적 정의"],"ref":{"tab":"concepts","idx":2},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-02","grade":"u"},
{"id":"kor-u-write-02#c3","kind":"concept","title":"읽으며 메모하기: 주석과 질문 달기","text":"학술적 글은 읽으면서 메모해야 오래 남고, 나중에 글을 쓸 때도 쓸 수 있습니다. 여백에 다는 주석 종류 · 예 요약 · \"핵심: 수면 6시간 미만 → 평점 낮음\" 질문 · \"평점 하나로 학업 성취를 재도 될까?\" 반론 · \"평점이 낮아서 걱정에 잠을 못 잔 것일 수도\" 연결 · \"심리","keywords":["논지","주석","서지 정보"],"ref":{"tab":"concepts","idx":3},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-02","grade":"u"},
{"id":"kor-u-write-02#c4","kind":"concept","title":"비판적 독해: 전제와 한계 찾기","text":"비판적 독해는 글의 주장을 그대로 받아들이지 않고, 근거와 추론이 타당한지 따지며 읽는 것입니다. 약점만 찾는 읽기가 아니라, 장점과 한계를 공정하게 평가하는 읽기입니다. 숨은 전제 찾기 전제는 주장이 성립하려면 참이어야 하지만 글에 드러나 있지 않은 생각입니다. 온라인 강의 수강생의 ","keywords":["전제","한계","비판적 독해"],"ref":{"tab":"concepts","idx":4},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-02","grade":"u"},
{"id":"kor-u-write-02#t0","kind":"term","title":"초록","text":"논문의 연구 목적·방법·주요 결과·결론을 짧게 간추려 맨 앞에 싣는 글입니다.","keywords":["초록"],"ref":{"tab":"terms","idx":0},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-02","grade":"u"},
{"id":"kor-u-write-02#t1","kind":"term","title":"주제어","text":"논문의 핵심 내용을 나타내는 낱말 몇 개입니다. 초록 아래에 적으며, 논문을 검색할 때 쓰입니다.","keywords":["주제어"],"ref":{"tab":"terms","idx":1},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-02","grade":"u"},
{"id":"kor-u-write-02#t2","kind":"term","title":"연구 질문","text":"논문이 연구를 통해 답하고자 하는 물음입니다. 연구 문제라고도 하며, 대개 서론 끝부분에 밝힙니다.","keywords":["연구 질문"],"ref":{"tab":"terms","idx":2},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-02","grade":"u"},
{"id":"kor-u-write-02#t3","kind":"term","title":"논지","text":"글 전체에서 글쓴이가 내세우는 중심 주장입니다. 연구 질문에 대한 글쓴이의 답입니다.","keywords":["논지"],"ref":{"tab":"terms","idx":3},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-02","grade":"u"},
{"id":"kor-u-write-02#t4","kind":"term","title":"조작적 정의","text":"추상적인 개념을 측정할 수 있는 기준으로 정하는 것입니다. 예: \"학업 스트레스\"를 \"20문항 설문지 점수의 합\"으로 정함","keywords":["조작적 정의"],"ref":{"tab":"terms","idx":4},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-02","grade":"u"},
{"id":"kor-u-write-02#t5","kind":"term","title":"주석","text":"읽으면서 여백에 다는 메모입니다. 요약·질문·반론·연결 등을 적습니다.","keywords":["주석"],"ref":{"tab":"terms","idx":5},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-02","grade":"u"},
{"id":"kor-u-write-02#t6","kind":"term","title":"서지 정보","text":"자료를 다시 찾을 수 있게 하는 정보입니다. 저자, 연도, 제목, 실린 곳, 쪽수 등입니다.","keywords":["서지 정보"],"ref":{"tab":"terms","idx":6},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-02","grade":"u"},
{"id":"kor-u-write-02#t7","kind":"term","title":"전제","text":"주장이 성립하려면 참이어야 하지만 글에 드러나 있지 않은 생각입니다.","keywords":["전제"],"ref":{"tab":"terms","idx":7},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-02","grade":"u"},
{"id":"kor-u-write-02#t8","kind":"term","title":"한계","text":"연구가 대상·방법·기간·해석 면에서 밝히지 못한 점이나 결과를 넓혀 적용하기 어려운 점입니다.","keywords":["한계"],"ref":{"tab":"terms","idx":8},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-02","grade":"u"},
{"id":"kor-u-write-02#t9","kind":"term","title":"비판적 독해","text":"글의 근거와 추론이 타당한지 따지며, 장점과 한계를 공정하게 평가하는 읽기입니다.","keywords":["비판적 독해"],"ref":{"tab":"terms","idx":9},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-02","grade":"u"},
{"id":"kor-u-write-02#f0","kind":"faq","title":"논문이 너무 어려워요. 처음부터 다 이해해야 하나요?","text":"아닙니다. 처음에는 초록과 서론 끝(연구 질문), 결론(답)만 이해해도 충분합니다. 모르는 개념어는 표시해 두었다가 그 논문 안의 정의를 찾아보고, 그래도 어려우면 개론서나 전공 사전을 참고하십시오. 같은 주제의 논문을 몇 편 읽다 보면 되풀이되는 개념이 익숙해집니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-02","grade":"u"},
{"id":"kor-u-write-02#f1","kind":"faq","title":"초록만 읽고 그 논문을 인용해도 되나요?","text":"바람직하지 않습니다. 초록은 간추린 글이라 결과가 성립하는 조건, 조사 대상, 한계가 빠져 있는 경우가 많습니다. 초록만 보고 인용하면 논문이 말하지 않은 것까지 말한 것처럼 옮길 위험이 있습니다. 인용하는 내용은 반드시 본문에서 확인하고, 그 쪽수를 적어 두십시오.","keywords":["초록"],"ref":{"tab":"faq","idx":1},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-02","grade":"u"},
{"id":"kor-u-write-02#f2","kind":"faq","title":"전문가가 쓴 논문에도 한계가 있나요?","text":"모든 연구에는 한계가 있습니다. 조사할 수 있는 대상·기간·방법이 늘 제한되기 때문입니다. 그래서 논문의 결론에는 대개 글쓴이가 스스로 밝힌 한계가 있습니다. 한계가 있다고 그 논문이 쓸모없는 것은 아닙니다. 한계를 알고 그 범위 안에서 결과를 정확하게 쓰는 것이 학술적 읽기의 태도입니다.","keywords":["한계"],"ref":{"tab":"faq","idx":2},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-02","grade":"u"},
{"id":"kor-u-write-02#m0","kind":"mistake","title":"자주 하는 실수","text":"서론에 소개된 선행 연구의 주장을 그 논문의 논지로 착각하는 실수 — \"그러나\", \"이 글은\", \"따라서\" 뒤에 오는 글쓴이 자신의 주장을 찾습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-02","grade":"u"},
{"id":"kor-u-write-02#m1","kind":"mistake","title":"자주 하는 실수","text":"밑줄만 잔뜩 긋고 메모를 남기지 않는 실수 — 모든 문장에 밑줄을 그으면 핵심이 사라집니다. 요점은 한 줄로 적고, 의문은 질문으로 적어 둡니다.","keywords":[],"ref":{"tab":"faq"},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-02","grade":"u"},
{"id":"kor-u-write-02#m2","kind":"mistake","title":"자주 하는 실수","text":"\"관련이 있다\"는 결과를 \"원인이다\"로 읽는 실수 — 두 가지가 함께 나타난다고 해서 하나가 다른 하나의 원인이라고 할 수는 없습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-02","grade":"u"},
{"id":"kor-u-write-03","kind":"unit","title":"요약과 바꿔 쓰기","text":"긴 글의 핵심을 정확하게 줄이는 요약의 원리와, 남의 생각을 내 문장으로 바꿔 쓰는 방법을 연습합니다. 삭제·선택·일반화·재구성의 원리를 적용하여 글을 요약할 수 있다. 목적과 분량에 맞는 형식으로 요약문을 쓸 수 있다. 원문의 뜻을 살려 내 낱말과 문장 구조로 바꿔 쓸 수 있다. 요약·바꿔 쓰기·직접 인용의 차이를 알고 목적에 맞게 골라 쓸 수 있다.","keywords":["요약","삭제","선택","일반화","재구성","중심 문장","바꿔 쓰기","직접 인용","짜깁기"],"ref":{"tab":"concepts","idx":0},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-03","grade":"u"},
{"id":"kor-u-write-03#c0","kind":"concept","title":"요약의 원리 ①: 삭제와 선택","text":"요약은 글의 핵심 내용을 원래 뜻을 살려 짧게 간추리는 것입니다. 요약에는 네 가지 원리가 쓰입니다. 원리 · 하는 일 삭제 · 중요하지 않은 내용을 지운다 선택 · 드러나 있는 중심 문장을 고른다 일반화 · 구체적인 낱말들을 상위 개념으로 묶는다 재구성 · 중심 문장이 없으면 새로 만","keywords":["요약","삭제","선택","일반화","재구성","중심 문장"],"ref":{"tab":"concepts","idx":0},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-03","grade":"u"},
{"id":"kor-u-write-03#c1","kind":"concept","title":"요약의 원리 ②: 일반화와 재구성","text":"일반화: 구체적인 낱말 여러 개를 그것들을 아우르는 상위 개념의 말로 묶습니다. \"이 연구는 설문 조사, 면담, 수업 관찰을 함께 사용하였다.\" → \"이 연구는 여러 가지 자료 수집 방법을 함께 사용하였다.\" 재구성: 단락에 중심 문장이 드러나 있지 않을 때, 여러 문장의 내용을 종합해","keywords":["요약","일반화","재구성","중심 문장"],"ref":{"tab":"concepts","idx":1},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-03","grade":"u"},
{"id":"kor-u-write-03#c2","kind":"concept","title":"요약문의 형식과 분량","text":"학술적 글쓰기에서 요약문은 다음 형식을 지킵니다. 첫 문장에 출처와 핵심 논지를 밝힙니다. 예: \"「대학 강의 녹화의 득과 실」의 글쓴이는 강의 녹화본을 복습 보조 자료로 써야 한다고 주장한다.\" 원문의 주요 근거를 원문의 비중과 흐름에 맞게 정리합니다. 원문이 중요하게 다룬 것을 더 ","keywords":["요약"],"ref":{"tab":"concepts","idx":2},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-03","grade":"u"},
{"id":"kor-u-write-03#c3","kind":"concept","title":"바꿔 쓰기(패러프레이즈)의 방법","text":"바꿔 쓰기(패러프레이즈)는 원문 일부의 뜻을 그대로 살리면서 내 낱말과 문장 구조로 다시 쓰는 것입니다. 요약과 달리 내용을 빠짐없이 옮기므로 분량은 원문의 그 부분과 비슷합니다. 바꿔 쓰는 순서 원문을 읽고 뜻을 정확히 이해합니다. 이해하지 못한 문장은 바꿔 쓸 수 없습니다. 원문을 ","keywords":["요약","바꿔 쓰기"],"ref":{"tab":"concepts","idx":3},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-03","grade":"u"},
{"id":"kor-u-write-03#c4","kind":"concept","title":"요약·바꿔 쓰기·직접 인용의 차이","text":"남의 글을 내 글에 가져오는 방법은 세 가지입니다. 셋 다 출처를 밝힌다는 점은 같습니다. 구분 · 직접 인용 · 바꿔 쓰기 · 요약 표현 · 원문 그대로, 따옴표 · 내 말 · 내 말 분량 · 원문과 같음 · 원문 그 부분과 비슷함 · 원문보다 훨씬 짧음 범위 · 짧은 구절·문장 · ","keywords":["요약","바꿔 쓰기","직접 인용"],"ref":{"tab":"concepts","idx":4},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-03","grade":"u"},
{"id":"kor-u-write-03#t0","kind":"term","title":"요약","text":"글의 핵심 내용을 원래 뜻을 살려 짧게 간추리는 것입니다.","keywords":["요약"],"ref":{"tab":"terms","idx":0},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-03","grade":"u"},
{"id":"kor-u-write-03#t1","kind":"term","title":"삭제","text":"요약의 원리. 예시·되풀이·덧붙인 설명처럼 중요하지 않은 내용을 지웁니다.","keywords":["삭제"],"ref":{"tab":"terms","idx":1},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-03","grade":"u"},
{"id":"kor-u-write-03#t2","kind":"term","title":"선택","text":"요약의 원리. 글에 드러나 있는 중심 문장을 골라 남깁니다.","keywords":["선택"],"ref":{"tab":"terms","idx":2},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-03","grade":"u"},
{"id":"kor-u-write-03#t3","kind":"term","title":"일반화","text":"요약의 원리. 구체적인 낱말 여러 개를 상위 개념의 말로 묶습니다. 예: 쌀·보리·밀 → 곡물","keywords":["일반화"],"ref":{"tab":"terms","idx":3},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-03","grade":"u"},
{"id":"kor-u-write-03#t4","kind":"term","title":"재구성","text":"요약의 원리. 중심 문장이 드러나 있지 않을 때 여러 문장의 내용을 종합해 중심 내용을 새 문장으로 만듭니다.","keywords":["재구성"],"ref":{"tab":"terms","idx":4},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-03","grade":"u"},
{"id":"kor-u-write-03#t5","kind":"term","title":"중심 문장","text":"단락의 중심 생각을 담은 문장입니다. 단락의 처음이나 끝에 오는 경우가 많습니다.","keywords":["중심 문장"],"ref":{"tab":"terms","idx":5},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-03","grade":"u"},
{"id":"kor-u-write-03#t6","kind":"term","title":"바꿔 쓰기","text":"원문 일부의 뜻을 살리면서 내 낱말과 문장 구조로 다시 쓰는 것입니다. 패러프레이즈라고도 하며 출처를 밝힙니다.","keywords":["바꿔 쓰기"],"ref":{"tab":"terms","idx":6},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-03","grade":"u"},
{"id":"kor-u-write-03#t7","kind":"term","title":"직접 인용","text":"원문의 표현을 그대로 가져와 따옴표로 묶고 출처를 밝히는 것입니다.","keywords":["직접 인용"],"ref":{"tab":"terms","idx":7},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-03","grade":"u"},
{"id":"kor-u-write-03#t8","kind":"term","title":"짜깁기","text":"원문의 문장 구조를 그대로 둔 채 낱말 몇 개만 바꾸어 쓰는 것입니다. 바꿔 쓰기로 인정되지 않고 표절로 볼 수 있습니다.","keywords":["짜깁기"],"ref":{"tab":"terms","idx":8},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-03","grade":"u"},
{"id":"kor-u-write-03#f0","kind":"faq","title":"요약할 때 원문의 낱말을 하나도 쓰면 안 되나요?","text":"그렇지 않습니다. \"열섬 현상\", \"조작적 정의\" 같은 핵심 용어나 고유 명사는 바꾸면 오히려 뜻이 흐려지므로 그대로 씁니다. 다만 원문의 문장을 그대로 이어 붙이면 안 되고, 글쓴이만의 독특한 표현을 그대로 쓰고 싶다면 따옴표로 묶어 직접 인용합니다.","keywords":["요약"],"ref":{"tab":"faq","idx":0},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-03","grade":"u"},
{"id":"kor-u-write-03#f1","kind":"faq","title":"바꿔 쓰기를 했더니 원문보다 짧아졌어요. 괜찮은가요?","text":"조금 짧아지는 것은 괜찮지만, 많이 짧아졌다면 내용이 빠졌을 가능성이 큽니다. 바꿔 쓰기는 원문 그 부분의 내용을 빠짐없이 옮기는 것이라 분량이 비슷합니다. 핵심만 남기려는 것이었다면 그것은 요약입니다. 어느 쪽이든 원문과 대조해 빠진 내용이나 달라진 뜻이 없는지 확인하십시오.","keywords":["바꿔 쓰기"],"ref":{"tab":"faq","idx":1},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-03","grade":"u"},
{"id":"kor-u-write-03#f2","kind":"faq","title":"요약문에 제 의견을 쓰고 싶으면 어떻게 하나요?","text":"요약을 먼저 마친 뒤 단락을 나누어 씁니다. \"이 글의 주장은 ~라는 점에서 설득력이 있다. 그러나 ~\"처럼 요약과 평가의 경계가 분명히 보이게 쓰면 됩니다. 요약 안에 의견을 섞으면 독자가 원문의 주장과 내 의견을 구별할 수 없습니다.","keywords":["요약"],"ref":{"tab":"faq","idx":2},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-03","grade":"u"},
{"id":"kor-u-write-03#m0","kind":"mistake","title":"자주 하는 실수","text":"원문 문장을 골라 그대로 이어 붙이고 요약이라고 하는 실수 — 요약은 원리를 적용해 줄인 뒤 내 문장으로 다시 씁니다.","keywords":[],"ref":{"tab":"faq"},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-03","grade":"u"},
{"id":"kor-u-write-03#m1","kind":"mistake","title":"자주 하는 실수","text":"낱말 몇 개만 비슷한 말로 바꾸고 바꿔 쓰기를 했다고 여기는 실수 — 원문을 덮고 문장 구조까지 새로 짜야 합니다. 낱말만 바꾼 것은 짜깁기입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-03","grade":"u"},
{"id":"kor-u-write-03#m2","kind":"mistake","title":"자주 하는 실수","text":"요약하면서 \"다만 ~에서만\", \"~일 가능성\" 같은 조건과 단서를 지우는 실수 — 원문보다 강한 주장이 되어 뜻이 달라집니다.","keywords":[],"ref":{"tab":"faq"},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-03","grade":"u"},
{"id":"kor-u-write-04","kind":"unit","title":"주제 설정과 개요 짜기","text":"넓은 화제를 다룰 만한 주제로 좁혀 연구 질문과 논지를 세우고, 서론·본론·결론의 개요를 짜는 법을 배웁니다. 대상·시기·공간·측면을 한정하여 넓은 화제를 다룰 만한 주제로 좁힐 수 있다. 좋은 연구 질문의 조건을 알고, 그에 대한 답으로 논지를 세울 수 있다. 화제식 개요와 문장식 개요의 특징을 알고 목적에 맞게 개요를 짤 수 있다. 서론·본론·결론의 …","keywords":["화제","주제","연구 질문","논지","개요","화제식 개요","문장식 개요","서론","본론","결론"],"ref":{"tab":"concepts","idx":0},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-04","grade":"u"},
{"id":"kor-u-write-04#c0","kind":"concept","title":"화제에서 주제로: 범위 좁히기","text":"화제는 글이 다룰 넓은 대상입니다(\"환경 문제\", \"대학생의 아르바이트\"). 화제 그대로는 무엇을 말할지 정해지지 않아서 글을 쓸 수 없습니다. 그래서 화제를 주어진 분량과 기간 안에서 다룰 수 있는 주제로 좁힙니다. 범위를 좁히는 기준은 다음과 같습니다. 기준 · 묻는 것 · 예 대상","keywords":["화제","주제"],"ref":{"tab":"concepts","idx":0},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-04","grade":"u"},
{"id":"kor-u-write-04#c1","kind":"concept","title":"연구 질문 세우기","text":"주제를 정했으면 그 주제에 대해 무엇을 알아내려는지를 물음으로 만듭니다. 이것이 연구 질문입니다. 연구 질문이 있어야 어떤 자료를 찾고 무엇을 분석할지 정할 수 있습니다. 좋은 연구 질문의 조건은 다음과 같습니다. 답이 열려 있다: 사실 하나로 바로 답이 끝나거나 답이 이미 정해진 물음","keywords":["주제","연구 질문"],"ref":{"tab":"concepts","idx":1},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-04","grade":"u"},
{"id":"kor-u-write-04#c2","kind":"concept","title":"논지 세우기","text":"논지는 연구 질문에 대한 글쓴이의 답을 한 문장의 주장으로 나타낸 것입니다. 글 전체는 이 논지를 뒷받침하기 위해 존재합니다. 좋은 논지의 조건은 다음과 같습니다. 분명한 주장이다: 다른 의견이 있을 수 있는 내용을 한쪽 입장으로 밝힙니다. 구체적이다: 무엇을, 왜, 어떻게가 드러납니다","keywords":["화제","연구 질문","논지"],"ref":{"tab":"concepts","idx":2},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-04","grade":"u"},
{"id":"kor-u-write-04#c3","kind":"concept","title":"개요의 종류: 화제식 개요와 문장식 개요","text":"개요는 글의 설계도입니다. 쓸 내용을 항목으로 나누고, 상위·하위 관계와 순서를 정해 배열합니다. 번호는 흔히 \"Ⅰ. → 1. → 가.\"의 차례로 매깁니다. 개요를 짤 때 지킬 원칙 같은 층위의 항목은 대등한 내용이어야 합니다. 하위 항목은 상위 항목에 포함되어야 합니다. 하위 항목으로","keywords":["화제","주제","개요","화제식 개요","문장식 개요"],"ref":{"tab":"concepts","idx":3},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-04","grade":"u"},
{"id":"kor-u-write-04#c4","kind":"concept","title":"서론·본론·결론의 기능","text":"학술적 글은 대개 서론·본론·결론으로 짜이며, 부분마다 맡은 일이 다릅니다. 부분 · 기능 서론 · 문제를 제기하고 배경을 밝힌다. 연구 질문과 논지를 제시하고, 필요하면 핵심 용어를 정의하며, 글의 전개 순서를 안내한다 본론 · 논지를 뒷받침하는 하위 주장들을 근거와 함께 펼친다. 단","keywords":["주제","연구 질문","논지","서론","본론","결론"],"ref":{"tab":"concepts","idx":4},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-04","grade":"u"},
{"id":"kor-u-write-04#t0","kind":"term","title":"화제","text":"글이 다룰 넓은 대상입니다. 예: \"환경 문제\", \"대학생의 아르바이트\"","keywords":["화제"],"ref":{"tab":"terms","idx":0},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-04","grade":"u"},
{"id":"kor-u-write-04#t1","kind":"term","title":"주제","text":"화제를 대상·시기·공간·측면으로 좁혀, 글에서 실제로 다룰 범위와 중심 내용을 정한 것입니다.","keywords":["주제"],"ref":{"tab":"terms","idx":1},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-04","grade":"u"},
{"id":"kor-u-write-04#t2","kind":"term","title":"연구 질문","text":"글이 조사와 분석으로 답하려는 물음입니다. 답이 열려 있고, 범위가 알맞으며, 자료로 답할 수 있어야 합니다.","keywords":["연구 질문"],"ref":{"tab":"terms","idx":2},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-04","grade":"u"},
{"id":"kor-u-write-04#t3","kind":"term","title":"논지","text":"연구 질문에 대한 글쓴이의 답을 한 문장의 분명하고 구체적인 주장으로 나타낸 것입니다.","keywords":["논지"],"ref":{"tab":"terms","idx":3},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-04","grade":"u"},
{"id":"kor-u-write-04#t4","kind":"term","title":"개요","text":"글에 쓸 내용을 항목으로 나누고 상위·하위 관계와 순서를 정해 배열한 글의 설계도입니다.","keywords":["개요"],"ref":{"tab":"terms","idx":4},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-04","grade":"u"},
{"id":"kor-u-write-04#t5","kind":"term","title":"화제식 개요","text":"각 항목을 낱말이나 구로 짧게 적은 개요입니다. 예: \"일회용 컵 사용의 실태\"","keywords":["화제식 개요"],"ref":{"tab":"terms","idx":5},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-04","grade":"u"},
{"id":"kor-u-write-04#t6","kind":"term","title":"문장식 개요","text":"각 항목을 완결된 문장으로 적은 개요입니다. 항목이 그대로 단락의 중심 문장이 됩니다.","keywords":["문장식 개요"],"ref":{"tab":"terms","idx":6},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-04","grade":"u"},
{"id":"kor-u-write-04#t7","kind":"term","title":"서론","text":"문제를 제기하고 연구 질문·논지·전개 순서를 밝히는 글의 첫 부분입니다.","keywords":["서론"],"ref":{"tab":"terms","idx":7},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-04","grade":"u"},
{"id":"kor-u-write-04#t8","kind":"term","title":"본론","text":"논지를 뒷받침하는 하위 주장과 근거를 펼치는 글의 중심 부분입니다.","keywords":["본론"],"ref":{"tab":"terms","idx":8},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-04","grade":"u"},
{"id":"kor-u-write-04#t9","kind":"term","title":"결론","text":"논의를 정리하고 논지를 다시 확인하며 의의·한계·후속 과제를 밝히는 글의 끝부분입니다.","keywords":["결론"],"ref":{"tab":"terms","idx":9},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-04","grade":"u"},
{"id":"kor-u-write-04#f0","kind":"faq","title":"주제가 떠오르지 않아요. 어떻게 시작하나요?","text":"먼저 관심 있는 화제를 하나 정하고, 그 화제에 대해 떠오르는 낱말과 물음을 자유롭게 적어 보십시오(브레인스토밍). 그다음 대상·시기·공간·측면 가운데 하나씩 한정해 좁혀 갑니다. 관련 개론서나 논문의 결론에 있는 \"후속 연구\" 부분을 읽어 보는 것도 좋은 출발점입니다.","keywords":["주제"],"ref":{"tab":"faq","idx":0},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-04","grade":"u"},
{"id":"kor-u-write-04#f1","kind":"faq","title":"논지는 자료를 다 찾은 다음에 정해야 하지 않나요?","text":"처음에는 잠정적인 논지를 세워 두는 것이 좋습니다. 그래야 어떤 자료를 찾아야 할지 방향이 잡힙니다. 다만 자료를 읽다가 논지와 맞지 않는 근거가 나오면 논지를 고쳐야 합니다. 자료를 논지에 맞추어 골라 쓰는 것이 아니라, 논지를 자료에 맞추는 것이 정직한 학술적 글쓰기입니다.","keywords":["논지"],"ref":{"tab":"faq","idx":1},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-04","grade":"u"},
{"id":"kor-u-write-04#f2","kind":"faq","title":"화제식 개요와 문장식 개요 가운데 무엇이 더 좋은가요?","text":"목적에 따라 다릅니다. 짧은 글이나 처음 구상할 때는 화제식 개요가 빠르고 전체 짜임을 보기 좋습니다. 긴 보고서나 논리를 꼼꼼히 점검해야 할 때는 문장식 개요가 낫습니다. 화제식으로 짜임을 잡은 뒤 문장식으로 바꾸어 점검하는 방법도 좋습니다. 다만 한 개요 안에서는 한 방식으로 통일합니다.","keywords":["화제","개요","화제식 개요","문장식 개요"],"ref":{"tab":"faq","idx":2},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-04","grade":"u"},
{"id":"kor-u-write-04#m0","kind":"mistake","title":"자주 하는 실수","text":"주제를 넓게 잡아 무엇이든 조금씩 다루다 끝나는 실수 — 대상·시기·공간·측면을 한정해 분량 안에서 깊이 다룰 수 있게 좁힙니다.","keywords":[],"ref":{"tab":"faq"},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-04","grade":"u"},
{"id":"kor-u-write-04#m1","kind":"mistake","title":"자주 하는 실수","text":"사실 진술이나 화제를 논지로 착각하는 실수 — \"사용량이 30% 늘었다\"는 근거이고, \"일회용 컵에 대해 알아보자\"는 화제입니다. 논지는 분명한 주장이어야 합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-04","grade":"u"},
{"id":"kor-u-write-04#m2","kind":"mistake","title":"자주 하는 실수","text":"결론에서 새로운 논점이나 근거를 처음 꺼내는 실수 — 결론은 본론의 논의를 정리하고 논지를 다시 확인하는 자리입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-04","grade":"u"},
{"id":"kor-u-write-05","kind":"unit","title":"단락과 문장 다듬기","text":"소주제문과 뒷받침 문장으로 단락을 짜고, 단락을 매끄럽게 잇고, 학술적 글에 맞는 명료한 문장으로 다듬습니다. 소주제문과 뒷받침 문장으로 통일성 있는 단락을 짤 수 있다. 예시·비교·대조·인과·정의 등 단락 전개 방식을 구별하고 목적에 맞게 고를 수 있다. 연결과 전환 표현으로 단락 사이의 관계를 분명히 드러낼 수 있다. 정확한 용어와 간결한 문장으로 학…","keywords":["단락","소주제문","뒷받침 문장","통일성","완결성","두괄식","연결 표현","번역 투"],"ref":{"tab":"concepts","idx":0},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-05","grade":"u"},
{"id":"kor-u-write-05#c0","kind":"concept","title":"단락의 뼈대: 소주제문과 뒷받침 문장","text":"단락(문단)은 하나의 중심 생각을 담은 글의 단위입니다. 그 중심 생각을 한 문장으로 드러낸 것이 소주제문이고, 소주제문을 설명하거나 증명하는 나머지 문장이 뒷받침 문장입니다. ① 대학의 글쓰기는 고등학교의 글쓰기와 목적이 다르다. ② 고등학교에서는 배운 내용을 정확히 정리하는 글을 주","keywords":["단락","소주제문","뒷받침 문장","두괄식"],"ref":{"tab":"concepts","idx":0},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-05","grade":"u"},
{"id":"kor-u-write-05#c1","kind":"concept","title":"단락 전개 방식: 예시·비교·대조·인과·정의","text":"뒷받침 문장을 어떤 방식으로 펼칠지에 따라 단락의 모양이 달라집니다. 자주 쓰는 단락 전개 방식은 다음과 같습니다. 방식 · 하는 일 · 자주 쓰는 표현 정의 · 개념의 뜻과 범위를 밝힌다 · \"A란 B이다\", \"~을 가리킨다\" 예시 · 구체적인 사례로 소주제를 뒷받침한다 · 예컨대, ","keywords":["단락","소주제문","뒷받침 문장"],"ref":{"tab":"concepts","idx":1},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-05","grade":"u"},
{"id":"kor-u-write-05#c2","kind":"concept","title":"단락 사이의 연결과 전환 표현","text":"단락 하나하나가 잘 짜여도 단락 사이가 끊기면 독자는 글의 흐름을 놓칩니다. 단락과 단락의 관계를 드러내는 말을 연결 표현이라고 합니다. 관계 · 연결 표현 덧붙임 · 또한, 게다가, 나아가 반대·한계 · 그러나, 하지만, 반면, 이와 달리 원인·결과 · 따라서, 그러므로, 그 결과 예","keywords":["단락","연결 표현"],"ref":{"tab":"concepts","idx":2},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-05","grade":"u"},
{"id":"kor-u-write-05#c3","kind":"concept","title":"학술 문장의 명료성 ①: 정확한 용어","text":"학술적 글의 독자는 문장을 한 가지 뜻으로만 읽을 수 있어야 합니다. 그 첫걸음은 정확한 용어입니다. 뜻이 정해진 용어를 쓴다. \"요즘 애들이 책을 잘 안 본다\"보다 \"청소년의 연간 독서량이 줄었다\"가 무엇을 재었는지 분명합니다. 한 개념에는 한 용어를 끝까지 쓴다. 앞에서 \"학습 동기","keywords":[],"ref":{"tab":"concepts","idx":3},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-05","grade":"u"},
{"id":"kor-u-write-05#c4","kind":"concept","title":"학술 문장의 명료성 ②: 간결한 문장","text":"정확한 용어를 골랐다면 이제 문장을 군더더기 없이 다듬습니다. 문제 · 고치기 전 · 고친 뒤 뜻이 겹치는 말 · 다시 재검토하다, 과반수 이상 · 재검토하다, 과반수 피동이 겹친 말 · 생각되어진다 · 생각된다 번역 투 · 연구에 있어서, 회의를 가졌다 · 연구에서, 회의를 했다 주어","keywords":["번역 투"],"ref":{"tab":"concepts","idx":4},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-05","grade":"u"},
{"id":"kor-u-write-05#t0","kind":"term","title":"단락","text":"하나의 중심 생각을 담은 글의 단위입니다. 문단이라고도 합니다.","keywords":["단락"],"ref":{"tab":"terms","idx":0},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-05","grade":"u"},
{"id":"kor-u-write-05#t1","kind":"term","title":"소주제문","text":"단락의 중심 생각을 한 문장으로 드러낸 문장입니다. 중심 문장이라고도 합니다.","keywords":["소주제문"],"ref":{"tab":"terms","idx":1},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-05","grade":"u"},
{"id":"kor-u-write-05#t2","kind":"term","title":"뒷받침 문장","text":"소주제문을 설명하거나 근거·사례를 들어 증명하는 문장입니다.","keywords":["뒷받침 문장"],"ref":{"tab":"terms","idx":2},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-05","grade":"u"},
{"id":"kor-u-write-05#t3","kind":"term","title":"통일성","text":"단락이나 글의 모든 문장이 하나의 중심 생각을 향하는 성질입니다.","keywords":["통일성"],"ref":{"tab":"terms","idx":3},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-05","grade":"u"},
{"id":"kor-u-write-05#t4","kind":"term","title":"완결성","text":"뒷받침 문장이 소주제문을 충분히 설명하거나 증명하는 성질입니다.","keywords":["완결성"],"ref":{"tab":"terms","idx":4},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-05","grade":"u"},
{"id":"kor-u-write-05#t5","kind":"term","title":"두괄식","text":"소주제문이 단락의 앞에 오는 짜임입니다. 학술적 글에서 많이 씁니다. 끝에 오면 미괄식, 앞과 끝에 모두 오면 양괄식입니다.","keywords":["두괄식"],"ref":{"tab":"terms","idx":5},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-05","grade":"u"},
{"id":"kor-u-write-05#t6","kind":"term","title":"연결 표현","text":"문장이나 단락 사이의 관계(덧붙임·반대·인과·예시·전환·요약)를 드러내는 말입니다. 예: 그러나, 따라서, 예컨대, 한편","keywords":["연결 표현"],"ref":{"tab":"terms","idx":6},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-05","grade":"u"},
{"id":"kor-u-write-05#t7","kind":"term","title":"번역 투","text":"외국어 문장의 짜임을 그대로 옮겨 우리말로 어색한 표현입니다. 예: \"~에 있어서\", \"회의를 가지다\"","keywords":["번역 투"],"ref":{"tab":"terms","idx":7},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-05","grade":"u"},
{"id":"kor-u-write-05#f0","kind":"faq","title":"소주제문은 꼭 단락 맨 앞에 와야 하나요?","text":"꼭 그렇지는 않습니다. 미괄식이나 양괄식도 쓸 수 있습니다. 다만 학술적 글은 독자가 요지를 빨리 잡도록 두괄식을 많이 씁니다. 사례를 먼저 보여 주고 결론을 끌어내는 것이 효과적일 때는 미괄식을 씁니다.","keywords":["단락","소주제문"],"ref":{"tab":"faq","idx":0},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-05","grade":"u"},
{"id":"kor-u-write-05#f1","kind":"faq","title":"단락은 몇 문장으로 써야 하나요?","text":"정해진 문장 수는 없습니다. 기준은 중심 생각 하나입니다. 한 문장짜리 단락은 뒷받침이 모자라기 쉽고, 지나치게 긴 단락은 중심 생각이 둘 이상 섞였을 가능성이 큽니다. 단락이 길어지면 중심 생각이 하나인지 먼저 확인해 보세요.","keywords":["단락"],"ref":{"tab":"faq","idx":1},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-05","grade":"u"},
{"id":"kor-u-write-05#f2","kind":"faq","title":"\"그러나\", \"따라서\" 같은 말을 문장마다 넣으면 더 논리적으로 보이지 않나요?","text":"그렇지 않습니다. 연결 표현은 관계를 드러낼 필요가 있는 곳에만 씁니다. 관계가 분명한 문장 사이에 연결어를 남발하면 글이 무거워지고, 관계에 맞지 않는 연결어는 오히려 논리를 흐립니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-05","grade":"u"},
{"id":"kor-u-write-05#f3","kind":"faq","title":"어려운 한자어를 많이 쓰면 학술적인 글이 되나요?","text":"아닙니다. 학술 문장의 기준은 정확성과 명료성입니다. 뜻이 정해진 전문 용어는 써야 하지만, 쉬운 말로 같은 뜻을 전할 수 있는데 굳이 어려운 말을 고를 필요는 없습니다.","keywords":[],"ref":{"tab":"faq","idx":3},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-05","grade":"u"},
{"id":"kor-u-write-05#m0","kind":"mistake","title":"자주 하는 실수","text":"한 단락에 중심 생각을 두세 개 담는 실수 — 단락을 한 문장으로 요약해 보고, 요약이 안 되면 단락을 나눕니다.","keywords":[],"ref":{"tab":"faq"},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-05","grade":"u"},
{"id":"kor-u-write-05#m1","kind":"mistake","title":"자주 하는 실수","text":"관계에 맞지 않는 연결 표현(\"따라서\"를 원인·결과가 아닌 곳에 쓰기) — 두 문장의 관계를 먼저 따진 뒤 연결어를 고릅니다.","keywords":[],"ref":{"tab":"faq"},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-05","grade":"u"},
{"id":"kor-u-write-05#m2","kind":"mistake","title":"자주 하는 실수","text":"\"다시 재검토\", \"과반수 이상\", \"생각되어진다\"처럼 뜻이나 피동이 겹치는 말 — 겹친 부분을 하나만 남깁니다.","keywords":[],"ref":{"tab":"faq"},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-05","grade":"u"},
{"id":"kor-u-write-06","kind":"unit","title":"논증과 비판적 사고","text":"주장·근거·보장·반박으로 이루어진 논증의 구조를 분석하고, 오류를 피하며 설득력 있게 논증합니다. 툴민 논증 모형의 요소(주장·근거·보장·뒷받침·한정·반박)로 논증의 구조를 분석할 수 있다. 연역 논증의 타당성과 귀납 논증의 강도를 구별하여 평가할 수 있다. 허수아비·미끄러운 비탈·순환 논증 같은 비형식적 오류를 찾아낼 수 있다. 반론을 예상하고 재반박하…","keywords":["논증","보장","뒷받침","한정","타당성","건전성","귀납 논증의 강도","허수아비 오류","미끄러운 비탈의 오류","순환 논증"],"ref":{"tab":"concepts","idx":0},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-06","grade":"u"},
{"id":"kor-u-write-06#c0","kind":"concept","title":"툴민 논증 모형: 논증을 이루는 여섯 요소","text":"영국의 철학자 툴민은 일상과 학문에서 쓰이는 논증을 여섯 요소로 나누어 분석했습니다. 요소 · 하는 일 · 묻는 질문 주장 · 논증이 내세우는 결론 · 무엇을 주장하는가? 근거 · 주장을 받치는 이번 경우의 구체적인 사실·자료 · 무엇을 바탕으로? 보장 · 근거에서 주장으로 넘어가게 해","keywords":["논증","보장","뒷받침","한정"],"ref":{"tab":"concepts","idx":0},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-06","grade":"u"},
{"id":"kor-u-write-06#c1","kind":"concept","title":"연역 논증: 타당성과 건전성","text":"연역 논증은 전제가 참이라면 결론이 반드시 참이 되도록 의도한 논증입니다. 연역 논증은 타당성으로 평가합니다. 타당한 논증: 전제가 모두 참이라면 결론이 거짓일 수 없는 논증. 타당성은 논증의 형식에 달려 있습니다. 건전한 논증: 타당하면서 전제도 실제로 모두 참인 논증. 모든 새는 날","keywords":["논증","타당성","건전성"],"ref":{"tab":"concepts","idx":1},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-06","grade":"u"},
{"id":"kor-u-write-06#c2","kind":"concept","title":"귀납 논증: 강도로 평가하기","text":"귀납 논증은 전제가 결론을 그럴듯하게 만드는 논증입니다. 전제가 모두 참이어도 결론이 거짓일 가능성이 남습니다. 그래서 귀납 논증은 타당·부당이 아니라 강하다·약하다로 평가합니다. 귀납 논증을 강하게 만드는 조건은 다음과 같습니다. 표본이 충분히 크다: 학생 5명보다 500명을 조사한 ","keywords":["논증","뒷받침"],"ref":{"tab":"concepts","idx":2},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-06","grade":"u"},
{"id":"kor-u-write-06#c3","kind":"concept","title":"비형식적 오류 심화: 허수아비·미끄러운 비탈·순환 논증","text":"형식은 그럴듯해 보이지만 내용이나 맥락 때문에 잘못된 추론을 비형식적 오류라고 합니다. 학술적 토론에서 특히 자주 나오는 세 가지를 봅니다. 허수아비 오류: 상대의 주장을 왜곡하거나 부풀려 반박하기 쉬운 모습(허수아비)으로 바꾼 뒤, 그것을 쓰러뜨리고 상대를 이겼다고 여기는 오류입니다.","keywords":["논증","허수아비 오류","미끄러운 비탈의 오류","순환 논증"],"ref":{"tab":"concepts","idx":3},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-06","grade":"u"},
{"id":"kor-u-write-06#c4","kind":"concept","title":"반론 예상과 재반박","text":"설득력 있는 논증은 자기 주장만 늘어놓지 않습니다. 독자가 떠올릴 반론을 먼저 꺼내고 그에 답합니다(재반박). 반론을 무시하면 독자는 \"글쓴이가 이 점을 모르는구나\"라고 생각합니다. 흔히 쓰는 흐름은 다음과 같습니다. 반론 소개: \"물론 ~라는 지적도 있다.\" 인정할 부분 인정: \"이 ","keywords":["논증"],"ref":{"tab":"concepts","idx":4},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-06","grade":"u"},
{"id":"kor-u-write-06#c5","kind":"concept","title":"논증적 글의 구조","text":"논증적 글(소논문, 칼럼, 비평문, 학술 에세이)은 대개 다음 짜임을 따릅니다. 부분 · 하는 일 서론 · 문제를 제기하고 배경을 밝힌 뒤, 글 전체의 논제(중심 주장)를 한 문장으로 제시한다 본론 ① · 첫째 근거와 그 근거를 받치는 자료 본론 ② · 둘째 근거와 자료 (근거마다 단락","keywords":["논증","뒷받침"],"ref":{"tab":"concepts","idx":5},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-06","grade":"u"},
{"id":"kor-u-write-06#t0","kind":"term","title":"논증","text":"근거를 들어 주장이 옳음을 보이는 말이나 글입니다.","keywords":["논증"],"ref":{"tab":"terms","idx":0},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-06","grade":"u"},
{"id":"kor-u-write-06#t1","kind":"term","title":"보장","text":"툴민 모형에서 근거와 주장을 이어 주는 일반 원리입니다. 논거·이유라고도 부르며, 흔히 생략됩니다.","keywords":["보장"],"ref":{"tab":"terms","idx":1},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-06","grade":"u"},
{"id":"kor-u-write-06#t2","kind":"term","title":"뒷받침","text":"툴민 모형에서 보장이 믿을 만한 까닭을 받쳐 주는 추가 자료입니다. 보강이라고도 합니다.","keywords":["뒷받침"],"ref":{"tab":"terms","idx":2},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-06","grade":"u"},
{"id":"kor-u-write-06#t3","kind":"term","title":"한정","text":"툴민 모형에서 주장의 확실성 정도를 나타내는 말입니다. 예: 아마, 대체로, 십중팔구","keywords":["한정"],"ref":{"tab":"terms","idx":3},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-06","grade":"u"},
{"id":"kor-u-write-06#t4","kind":"term","title":"타당성","text":"연역 논증에서 전제가 모두 참이라면 결론이 반드시 참이 되는 성질입니다. 전제의 실제 참·거짓과는 별개로 형식에 달려 있습니다.","keywords":["타당성"],"ref":{"tab":"terms","idx":4},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-06","grade":"u"},
{"id":"kor-u-write-06#t5","kind":"term","title":"건전성","text":"연역 논증이 타당하면서 전제도 실제로 모두 참인 성질입니다.","keywords":["건전성"],"ref":{"tab":"terms","idx":5},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-06","grade":"u"},
{"id":"kor-u-write-06#t6","kind":"term","title":"귀납 논증의 강도","text":"귀납 논증의 전제가 결론을 얼마나 그럴듯하게 만드는지의 정도입니다. 표본의 크기와 대표성 등에 따라 강하거나 약합니다.","keywords":["귀납 논증의 강도"],"ref":{"tab":"terms","idx":6},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-06","grade":"u"},
{"id":"kor-u-write-06#t7","kind":"term","title":"허수아비 오류","text":"상대의 주장을 왜곡하거나 부풀린 뒤 그것을 공격하는 오류입니다.","keywords":["허수아비 오류"],"ref":{"tab":"terms","idx":7},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-06","grade":"u"},
{"id":"kor-u-write-06#t8","kind":"term","title":"미끄러운 비탈의 오류","text":"첫 단계를 허용하면 근거 없이 연쇄적으로 극단적 결과에 이른다고 주장하는 오류입니다.","keywords":["미끄러운 비탈의 오류"],"ref":{"tab":"terms","idx":8},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-06","grade":"u"},
{"id":"kor-u-write-06#t9","kind":"term","title":"순환 논증","text":"증명해야 할 결론을 전제에 미리 넣어 두는 오류입니다. 선결 문제 요구의 오류라고도 합니다.","keywords":["순환 논증"],"ref":{"tab":"terms","idx":9},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-06","grade":"u"},
{"id":"kor-u-write-06#f0","kind":"faq","title":"보장과 근거는 어떻게 구별하나요?","text":"근거는 이번 경우에 관한 구체적인 사실이고, 보장은 여러 경우에 두루 적용되는 일반 원리입니다. \"이 식당은 줄이 길다\"는 근거, \"줄이 긴 식당은 대체로 맛있다\"는 보장입니다. 근거에서 주장으로 넘어가며 \"왜 그렇게 말할 수 있지?\"라고 물었을 때의 답이 보장입니다.","keywords":["보장"],"ref":{"tab":"faq","idx":0},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-06","grade":"u"},
{"id":"kor-u-write-06#f1","kind":"faq","title":"결론이 참인데 왜 부당한 논증이라고 하나요?","text":"타당성은 결론이 참인지가 아니라, 전제에서 결론이 반드시 따라 나오는지를 봅니다. \"모든 장미는 꽃이다. 어떤 꽃은 빨갛다. 그러므로 어떤 장미는 빨갛다.\"는 결론이 실제로 참이지만, 빨간 꽃이 모두 장미가 아닌 꽃이어도 전제는 참일 수 있으므로 부당합니다.","keywords":["논증"],"ref":{"tab":"faq","idx":1},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-06","grade":"u"},
{"id":"kor-u-write-06#f2","kind":"faq","title":"귀납 논증의 결론은 틀릴 수도 있는데, 학문에서 왜 쓰나요?","text":"관찰과 실험에서 일반 법칙을 끌어내는 일은 대부분 귀납입니다. 귀납은 확실성을 주지는 못하지만, 근거가 크고 대표성이 있을수록 매우 믿을 만한 결론을 줍니다. 그래서 학술적 글은 귀납적 결론에 \"이 자료의 범위에서는\" 같은 한정을 붙여 근거만큼만 주장합니다.","keywords":["논증"],"ref":{"tab":"faq","idx":2},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-06","grade":"u"},
{"id":"kor-u-write-06#f3","kind":"faq","title":"반론을 소개하면 글이 길어지는데 꼭 넣어야 하나요?","text":"논쟁적인 주제라면 넣는 것이 좋습니다. 독자 대부분이 떠올릴 만한 반론에 답하지 않으면 글쓴이가 그 점을 몰랐거나 피했다고 여겨집니다. 모든 반론을 다룰 필요는 없고, 가장 강하고 흔한 반론 한두 가지를 골라 다룹니다.","keywords":[],"ref":{"tab":"faq","idx":3},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-06","grade":"u"},
{"id":"kor-u-write-06#m0","kind":"mistake","title":"자주 하는 실수","text":"전제가 거짓이라는 이유로 \"부당하다\"고 판단하는 실수 — 타당성은 형식으로, 건전성은 전제의 참·거짓까지 따져 판단합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-06","grade":"u"},
{"id":"kor-u-write-06#m1","kind":"mistake","title":"자주 하는 실수","text":"반론을 일부러 약하게 소개하고 쉽게 이기는 실수 — 이것 자체가 허수아비 오류입니다. 반론은 가장 강한 형태로 소개합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-06","grade":"u"},
{"id":"kor-u-write-06#m2","kind":"mistake","title":"자주 하는 실수","text":"결론에서 본론에 없던 새 주장을 처음 꺼내는 실수 — 결론은 본론에서 근거를 댄 주장을 정리하는 자리입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-06","grade":"u"},
{"id":"kor-u-write-07","kind":"unit","title":"자료 찾기와 평가","text":"도서관과 학술 데이터베이스에서 자료를 찾고, 1차·2차 자료를 구분해 믿을 만한 자료인지 평가합니다. 도서관 목록과 학술 데이터베이스의 쓰임을 구별하여 자료를 찾을 수 있다. 검색어를 조합하고 검색 결과에 따라 검색 전략을 조정할 수 있다. 연구 질문에 비추어 1차 자료와 2차 자료를 구분할 수 있다. 저자·동료 심사·출판 시기 등으로 자료의 신뢰성을 평…","keywords":["학술 데이터베이스","청구 기호","불 연산자","1차 자료","2차 자료","동료 심사","서지 정보","초록"],"ref":{"tab":"concepts","idx":0},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-07","grade":"u"},
{"id":"kor-u-write-07#c0","kind":"concept","title":"도서관 목록과 학술 데이터베이스","text":"학술 자료를 찾는 길은 크게 둘입니다. 도구 · 무엇을 찾나 · 쓰임 도서관 목록(온라인 목록) · 그 도서관이 가진 책, 학위 논문, 학술지(잡지 단위) · 책이 서가 어디에 있는지(청구 기호), 대출 중인지 확인 학술 데이터베이스 · 학술지에 실린 논문 한 편 한 편, 초록, 원문 ","keywords":["학술 데이터베이스","청구 기호","초록"],"ref":{"tab":"concepts","idx":0},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-07","grade":"u"},
{"id":"kor-u-write-07#c1","kind":"concept","title":"검색어 조합과 검색 전략","text":"좋은 검색은 검색어 고르기에서 시작합니다. 연구 질문에서 핵심 개념을 뽑고, 개념마다 동의어·비슷한 말·영어 표현을 적어 둡니다. 연구 질문: 스마트폰 사용이 청소년의 수면에 미치는 영향 개념 ① 스마트폰 / 휴대 전화 / 모바일 기기 개념 ② 청소년 / 십대 / 중고등학생 개념 ③ 수","keywords":[],"ref":{"tab":"concepts","idx":1},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-07","grade":"u"},
{"id":"kor-u-write-07#c2","kind":"concept","title":"1차 자료와 2차 자료","text":"자료는 연구 대상과의 거리에 따라 나눌 수 있습니다. 1차 자료: 연구 대상을 직접 담은 원 자료. 실험·관찰·설문으로 직접 모은 자료, 일기·편지·공문서·회의록, 분석 대상인 문학 작품, 연구 결과를 처음 보고한 논문 등 2차 자료: 1차 자료를 해석·분석·요약한 자료. 평론, 개론서","keywords":["1차 자료","2차 자료"],"ref":{"tab":"concepts","idx":2},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-07","grade":"u"},
{"id":"kor-u-write-07#c3","kind":"concept","title":"학술 자료의 신뢰성 평가","text":"찾은 자료를 근거로 쓰기 전에 믿을 만한지 따져야 합니다. 다음 질문을 차례로 던져 봅니다. 기준 · 묻는 질문 저자 · 누가 썼는가? 그 주제에 전문성이 있는가? 이해관계(판매·홍보)는 없는가? 동료 심사 · 같은 분야 전문가의 검토를 거쳐 실렸는가? 출판 시기 · 언제 나왔는가? 이","keywords":["동료 심사"],"ref":{"tab":"concepts","idx":3},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-07","grade":"u"},
{"id":"kor-u-write-07#c4","kind":"concept","title":"자료 정리와 참고 문헌 관리","text":"자료를 잘 찾아도 정리하지 않으면 글을 쓸 때 \"이 내용을 어디서 봤더라?\" 하며 다시 찾게 됩니다. 더 큰 문제는 출처를 잃어버려 본의 아니게 표절하게 되는 것입니다. 1. 찾는 즉시 서지 정보를 적는다. 자료 · 적어 둘 것 책 · 저자, 출판 연도, 책 제목, 출판사, 인용한 쪽 ","keywords":["서지 정보"],"ref":{"tab":"concepts","idx":4},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-07","grade":"u"},
{"id":"kor-u-write-07#t0","kind":"term","title":"학술 데이터베이스","text":"학술지 논문 등을 한 편 단위로 모아 주제어·저자 등으로 찾고 초록과 원문을 볼 수 있게 한 검색 도구입니다.","keywords":["학술 데이터베이스"],"ref":{"tab":"terms","idx":0},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-07","grade":"u"},
{"id":"kor-u-write-07#t1","kind":"term","title":"청구 기호","text":"도서관에서 책이 꽂힌 자리를 알려 주는 번호입니다. 대개 분류 번호와 저자 기호 등으로 이루어집니다.","keywords":["청구 기호"],"ref":{"tab":"terms","idx":1},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-07","grade":"u"},
{"id":"kor-u-write-07#t2","kind":"term","title":"불 연산자","text":"검색어를 조합하는 AND(모두 포함), OR(하나라도 포함), NOT(빼기)을 함께 이르는 말입니다.","keywords":["불 연산자"],"ref":{"tab":"terms","idx":2},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-07","grade":"u"},
{"id":"kor-u-write-07#t3","kind":"term","title":"1차 자료","text":"연구 대상을 직접 담은 원 자료입니다. 예: 설문 응답, 일기, 회의록, 분석 대상인 작품, 연구 결과를 처음 보고한 논문","keywords":["1차 자료"],"ref":{"tab":"terms","idx":3},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-07","grade":"u"},
{"id":"kor-u-write-07#t4","kind":"term","title":"2차 자료","text":"1차 자료를 해석·분석·요약한 자료입니다. 예: 평론, 개론서, 검토 논문, 해설 기사","keywords":["2차 자료"],"ref":{"tab":"terms","idx":4},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-07","grade":"u"},
{"id":"kor-u-write-07#t5","kind":"term","title":"동료 심사","text":"학술지에 투고된 논문을 같은 분야 전문가들이 검토하여 게재 여부를 정하는 절차입니다.","keywords":["동료 심사"],"ref":{"tab":"terms","idx":5},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-07","grade":"u"},
{"id":"kor-u-write-07#t6","kind":"term","title":"서지 정보","text":"자료를 찾아갈 수 있게 해 주는 정보입니다. 저자, 연도, 제목, 출판사 또는 학술지 이름, 권·호, 쪽 등","keywords":["서지 정보"],"ref":{"tab":"terms","idx":6},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-07","grade":"u"},
{"id":"kor-u-write-07#t7","kind":"term","title":"초록","text":"논문의 목적·방법·결과·결론을 짧게 요약한 글입니다. 논문을 고를 때 먼저 읽습니다.","keywords":["초록"],"ref":{"tab":"terms","idx":7},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-07","grade":"u"},
{"id":"kor-u-write-07#f0","kind":"faq","title":"일반 검색 엔진으로 찾은 자료는 쓰면 안 되나요?","text":"쓸 수 있습니다. 다만 무엇이 나왔는지가 아니라 그 자료가 무엇인지를 따져야 합니다. 검색 엔진으로 찾았더라도 공공 기관 보고서나 학술지 논문이라면 신뢰성 기준에 따라 쓸 수 있습니다. 출처가 불분명한 글은 원 자료를 찾아가는 실마리로만 씁니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-07","grade":"u"},
{"id":"kor-u-write-07#f1","kind":"faq","title":"누구나 고칠 수 있는 온라인 백과사전은 인용해도 되나요?","text":"배경 지식을 얻는 출발점으로는 쓸모가 있지만, 학술적 글의 근거로 직접 인용하기는 알맞지 않습니다. 내용이 바뀔 수 있고 저자의 전문성을 확인하기 어렵기 때문입니다. 그 항목이 밝힌 출처를 따라가 원 자료를 확인하고 그것을 인용하세요.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-07","grade":"u"},
{"id":"kor-u-write-07#f2","kind":"faq","title":"자료는 몇 개쯤 모아야 하나요?","text":"정해진 수는 없습니다. 기준은 주장마다 믿을 만한 근거가 있는가, 주요 반론과 다른 관점도 살폈는가입니다. 한 자료에만 기대면 그 자료의 한계를 그대로 물려받으므로, 핵심 주장은 둘 이상의 독립된 자료로 확인하는 것이 좋습니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-07","grade":"u"},
{"id":"kor-u-write-07#m0","kind":"mistake","title":"자주 하는 실수","text":"2차 자료에 인용된 내용을 원 자료를 확인하지 않고 원문에서 본 것처럼 인용하는 실수 — 원 자료를 찾아 확인하고, 구할 수 없으면 재인용으로 밝힙니다.","keywords":[],"ref":{"tab":"faq"},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-07","grade":"u"},
{"id":"kor-u-write-07#m1","kind":"mistake","title":"자주 하는 실수","text":"검색 결과가 적다고 주제를 바로 바꾸는 실수 — 먼저 동의어를 OR로 더하고 더 넓은 말로 바꾸어 다시 검색해 봅니다.","keywords":[],"ref":{"tab":"faq"},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-07","grade":"u"},
{"id":"kor-u-write-07#m2","kind":"mistake","title":"자주 하는 실수","text":"자료를 찾을 때 서지 정보를 적지 않아 나중에 출처를 잃는 실수 — 찾은 그 자리에서 저자·연도·제목·쪽을 적습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-07","grade":"u"},
{"id":"kor-u-write-08","kind":"unit","title":"인용과 표절 예방","text":"직접 인용과 간접 인용, 각주와 참고 문헌 쓰는 법을 익히고, 표절의 유형을 알아 연구 윤리를 지킵니다. 직접 인용과 간접 인용을 목적에 맞게 골라 바르게 쓸 수 있다. 각주와 내주(저자-연도) 방식으로 출처를 표기할 수 있다. 본문의 인용과 짝이 맞는 참고 문헌 목록을 일정한 양식으로 작성할 수 있다. 표절의 유형을 구별하고, 생성형 인공지능을 쓸 때 …","keywords":["직접 인용","간접 인용","각주","내주","재인용","참고 문헌 목록","표절","짜깁기","자기 표절"],"ref":{"tab":"concepts","idx":0},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-08","grade":"u"},
{"id":"kor-u-write-08#c0","kind":"concept","title":"직접 인용과 간접 인용","text":"남의 글에서 빌려 온 내용은 반드시 출처를 밝힙니다. 빌려 오는 방법은 둘입니다. · 직접 인용 · 간접 인용 방법 · 원문을 글자 그대로 옮긴다 · 원문의 뜻을 자기 말로 바꾸어 쓴다(바꿔 쓰기·요약) 표시 · 따옴표로 묶고 출처와 쪽수를 밝힌다 · 따옴표 없이 출처를 밝힌다(쪽수는 ","keywords":["직접 인용","간접 인용"],"ref":{"tab":"concepts","idx":0},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-08","grade":"u"},
{"id":"kor-u-write-08#c1","kind":"concept","title":"출처 표기 방식: 각주와 내주","text":"글 안에서 출처를 밝히는 방식은 크게 둘입니다. 각주 방식: 인용한 자리에 번호를 달고, 같은 쪽 아래에 그 번호와 함께 출처를 적습니다. 인문학 분야에서 많이 씁니다. 본문: 단락은 \"하나의 생각을 담는 그릇\"이다.1) 쪽 아래: 1) 김지아, 『글쓰기의 기초』, 예시출판사, 2021","keywords":["직접 인용","각주","내주","참고 문헌 목록"],"ref":{"tab":"concepts","idx":1},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-08","grade":"u"},
{"id":"kor-u-write-08#c2","kind":"concept","title":"참고 문헌 목록 작성법","text":"참고 문헌 목록은 글에서 인용한 자료의 서지 정보를 글 끝에 모아 놓은 것입니다. 독자가 그 자료를 찾아가 확인할 수 있게 하는 것이 목적입니다. 1. 무엇을 넣나: 본문에서 실제로 인용한 자료를 넣습니다. 본문의 모든 인용은 목록에 있고, 목록의 모든 자료는 본문 어딘가에 인용되어 있","keywords":["참고 문헌 목록"],"ref":{"tab":"concepts","idx":2},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-08","grade":"u"},
{"id":"kor-u-write-08#c3","kind":"concept","title":"표절의 유형","text":"표절은 남의 글·생각·자료를 출처를 밝히지 않고 자기 것처럼 쓰는 일입니다. 위조·변조와 함께 대표적인 연구 부정행위로 꼽힙니다. 의도하지 않았더라도 결과가 표절이면 표절로 판단되므로, 인용 규칙을 정확히 아는 것이 중요합니다. 유형 · 모습 출처 누락 · 남의 문장·생각·그림·자료를 ","keywords":["재인용","표절","짜깁기","자기 표절"],"ref":{"tab":"concepts","idx":3},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-08","grade":"u"},
{"id":"kor-u-write-08#c4","kind":"concept","title":"생성형 인공지능을 쓸 때 밝히고 확인할 점","text":"생성형 인공지능은 글의 아이디어를 넓히거나 문장을 다듬는 데 도움을 줄 수 있지만, 학술적 글쓰기에서 쓸 때는 지켜야 할 점이 있습니다. 1. 먼저 지침을 확인한다. 쓸 수 있는지, 어디까지 쓸 수 있는지는 강의·학과·학술지마다 다릅니다. 금지한 과제에서 쓰면 그 자체로 부정행위가 됩니","keywords":[],"ref":{"tab":"concepts","idx":4},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-08","grade":"u"},
{"id":"kor-u-write-08#t0","kind":"term","title":"직접 인용","text":"원문을 글자 그대로 옮기고 따옴표로 묶어 출처와 쪽수를 밝히는 인용입니다.","keywords":["직접 인용"],"ref":{"tab":"terms","idx":0},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-08","grade":"u"},
{"id":"kor-u-write-08#t1","kind":"term","title":"간접 인용","text":"원문의 뜻을 자기 말과 구조로 바꾸어 쓰고 출처를 밝히는 인용입니다.","keywords":["간접 인용"],"ref":{"tab":"terms","idx":1},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-08","grade":"u"},
{"id":"kor-u-write-08#t2","kind":"term","title":"각주","text":"인용한 자리에 번호를 달고 같은 쪽 아래에 그 번호와 함께 출처나 설명을 적는 방식입니다.","keywords":["각주"],"ref":{"tab":"terms","idx":2},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-08","grade":"u"},
{"id":"kor-u-write-08#t3","kind":"term","title":"내주","text":"본문의 괄호 안에 저자와 연도(직접 인용이면 쪽수까지)를 적는 출처 표기 방식입니다. 저자-연도 방식이라고도 합니다.","keywords":["내주"],"ref":{"tab":"terms","idx":3},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-08","grade":"u"},
{"id":"kor-u-write-08#t4","kind":"term","title":"재인용","text":"원문을 직접 보지 못하고 다른 자료에 인용된 것을 옮길 때, 실제로 본 자료를 함께 밝히는 인용입니다.","keywords":["재인용"],"ref":{"tab":"terms","idx":4},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-08","grade":"u"},
{"id":"kor-u-write-08#t5","kind":"term","title":"참고 문헌 목록","text":"글에서 인용한 자료의 서지 정보를 일정한 양식과 순서로 글 끝에 모아 놓은 목록입니다.","keywords":["참고 문헌 목록"],"ref":{"tab":"terms","idx":5},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-08","grade":"u"},
{"id":"kor-u-write-08#t6","kind":"term","title":"표절","text":"남의 글·생각·자료를 출처를 밝히지 않고 자기 것처럼 쓰는 일입니다. 의도하지 않았어도 표절이 될 수 있습니다.","keywords":["표절"],"ref":{"tab":"terms","idx":6},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-08","grade":"u"},
{"id":"kor-u-write-08#t7","kind":"term","title":"짜깁기","text":"여러 출처의 문장을 이어 붙이거나 낱말만 바꾸어 섞어 자기 글처럼 만드는 표절입니다.","keywords":["짜깁기"],"ref":{"tab":"terms","idx":7},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-08","grade":"u"},
{"id":"kor-u-write-08#t8","kind":"term","title":"자기 표절","text":"자기가 이미 제출·발표한 글을 밝히지 않고 새 글처럼 다시 내는 일입니다. 중복 제출·중복 게재라고도 합니다.","keywords":["자기 표절"],"ref":{"tab":"terms","idx":8},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-08","grade":"u"},
{"id":"kor-u-write-08#f0","kind":"faq","title":"각주와 내주 가운데 무엇을 써야 하나요?","text":"과제나 학술지의 지침을 따릅니다. 지침이 없다면 그 분야에서 흔히 쓰는 방식을 고르되, 한 글 안에서는 한 방식으로 통일합니다. 대체로 인문학은 각주, 사회과학·자연과학은 내주를 많이 씁니다.","keywords":["각주","내주"],"ref":{"tab":"faq","idx":0},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-08","grade":"u"},
{"id":"kor-u-write-08#f1","kind":"faq","title":"몇 낱말 이상 같으면 표절인가요?","text":"정해진 낱말 수는 없습니다. 기준은 남의 표현이나 생각을 출처 없이 자기 것처럼 썼는가입니다. 짧은 구절이라도 독창적인 표현을 그대로 가져왔다면 따옴표와 출처가 필요하고, 문장을 완전히 바꾸었어도 남의 생각이면 출처가 필요합니다.","keywords":["표절"],"ref":{"tab":"faq","idx":1},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-08","grade":"u"},
{"id":"kor-u-write-08#f2","kind":"faq","title":"표절 검사 프로그램에서 일치율이 낮으면 괜찮은 건가요?","text":"꼭 그렇지는 않습니다. 검사 프로그램은 문자열이 겹치는 정도를 보여 줄 뿐입니다. 낱말을 바꾸어 일치율을 낮춘 짜깁기나, 출처 없이 빌린 생각은 잡아내지 못할 수 있습니다. 반대로 바르게 직접 인용한 부분도 일치로 표시될 수 있습니다. 숫자보다 인용 규칙을 지켰는가가 기준입니다.","keywords":["표절"],"ref":{"tab":"faq","idx":2},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-08","grade":"u"},
{"id":"kor-u-write-08#f3","kind":"faq","title":"생성형 인공지능으로 맞춤법만 고쳐도 밝혀야 하나요?","text":"강의와 학술지의 지침에 따릅니다. 맞춤법 검사 수준의 도움은 밝히지 않아도 되는 곳도 있고, 모든 사용을 밝히라는 곳도 있습니다. 지침이 분명하지 않으면 교수자에게 묻거나 사용 사실을 밝히는 편이 안전합니다.","keywords":[],"ref":{"tab":"faq","idx":3},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-08","grade":"u"},
{"id":"kor-u-write-08#m0","kind":"mistake","title":"자주 하는 실수","text":"간접 인용을 한다며 낱말 몇 개만 바꾸고 문장 구조는 그대로 두는 실수 — 원문을 덮고 내 문장과 구조로 다시 쓴 뒤 출처를 밝힙니다.","keywords":[],"ref":{"tab":"faq"},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-08","grade":"u"},
{"id":"kor-u-write-08#m1","kind":"mistake","title":"자주 하는 실수","text":"2차 자료에서 본 인용을 원문에서 본 것처럼 적는 실수 — 원문을 확인하지 못했다면 재인용으로 밝힙니다.","keywords":[],"ref":{"tab":"faq"},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-08","grade":"u"},
{"id":"kor-u-write-08#m2","kind":"mistake","title":"자주 하는 실수","text":"생성형 인공지능이 알려 준 참고 문헌을 확인하지 않고 옮기는 실수 — 실제로 있는지, 내용이 맞는지 원자료에서 확인합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-08","grade":"u"},
{"id":"kor-u-write-09","kind":"unit","title":"학술 보고서 쓰기","text":"보고서의 종류와 짜임을 알고, 표와 그림을 넣어 서론·본론·결론을 갖춘 학술 보고서를 완성하고 퇴고합니다. 과제의 성격에 맞게 요약·비평·조사·실험 보고서를 구별할 수 있다. 보고서의 짜임과 각 부분의 역할을 알고 내용을 알맞은 자리에 배치할 수 있다. 번호·제목·출처를 갖추어 표와 그림을 제시할 수 있다. 문제 제기와 연구 목적이 드러나는 서론, 결과·…","keywords":["학술 보고서","요약 보고서","비평 보고서","조사 보고서","실험 보고서","초록","고찰","참고문헌","부록","퇴고"],"ref":{"tab":"concepts","idx":0},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-09","grade":"u"},
{"id":"kor-u-write-09#c0","kind":"concept","title":"학술 보고서와 그 종류","text":"학술 보고서는 어떤 주제에 대해 자료를 읽거나 조사·실험한 결과를 정해진 형식에 따라 객관적으로 정리해 알리는 글입니다. 감상문과 달리, 읽는 사람이 근거와 방법을 확인할 수 있도록 출처와 절차를 밝힙니다. 대학 과제로 자주 나오는 보고서는 무엇을 하느냐에 따라 네 가지로 나눌 수 있습","keywords":["학술 보고서","요약 보고서","비평 보고서","조사 보고서","실험 보고서","고찰"],"ref":{"tab":"concepts","idx":0},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-09","grade":"u"},
{"id":"kor-u-write-09#c1","kind":"concept","title":"보고서의 짜임과 각 부분의 역할","text":"학술 보고서는 대체로 다음 짜임을 따릅니다. 짧은 과제 보고서에서는 표지·초록·차례를 빼기도 하므로 과제 안내를 먼저 확인합니다. 부분 · 역할 표지 · 제목, 과목, 제출자, 제출일 초록(요약) · 목적·방법·결과·결론을 한 문단으로 압축 서론 · 배경, 문제 제기, 연구 목적, 방법","keywords":["학술 보고서","실험 보고서","초록","고찰","참고문헌","부록"],"ref":{"tab":"concepts","idx":1},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-09","grade":"u"},
{"id":"kor-u-write-09#c2","kind":"concept","title":"표와 그림 제시하기: 번호·제목·출처","text":"표와 그림은 많은 수치나 관계를 한눈에 보여 줍니다. 대신 정해진 방식으로 제시해야 합니다. 번호: 표와 그림에 따로 번호를 매깁니다(표 1, 표 2 … / 그림 1, 그림 2 …). 그래프·사진·도식은 보통 \"그림\"으로 묶습니다. 제목: 무엇을 보여 주는지 구체적으로 씁니다. \"표 1","keywords":[],"ref":{"tab":"concepts","idx":2},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-09","grade":"u"},
{"id":"kor-u-write-09#c3","kind":"concept","title":"서론 쓰기: 문제 제기와 연구 목적","text":"서론은 \"왜 이 글을 읽어야 하는가\"에 답하는 부분입니다. 보통 다음 흐름을 따릅니다. 배경: 주제가 어떤 맥락에 놓여 있는지 문제 제기: 무엇이 아직 밝혀지지 않았거나 문제인지 연구 목적(연구 문제): 이 보고서가 무엇을 밝히려는지 방법과 범위: 무엇을, 어떻게, 어디까지 다루는지 글","keywords":[],"ref":{"tab":"concepts","idx":3},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-09","grade":"u"},
{"id":"kor-u-write-09#c4","kind":"concept","title":"결론 쓰기: 요약·의의·한계·제언","text":"결론은 서론에서 던진 질문에 답하고 글을 닫는 부분입니다. 보통 네 가지를 담습니다. 결과 요약: 본론에서 밝힌 것을 연구 질문에 대한 답으로 정리 의의: 이 결과가 무엇에 도움이 되는지 한계: 대상·방법·범위에서 부족했던 점 제언: 후속 연구나 실천에 대한 제안 결론에서 피할 것도 있","keywords":[],"ref":{"tab":"concepts","idx":4},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-09","grade":"u"},
{"id":"kor-u-write-09#c5","kind":"concept","title":"퇴고 점검표","text":"퇴고는 다 쓴 글을 다시 읽으며 고치는 일입니다. 큰 단위에서 작은 단위로 내려가며 점검해야 헛수고가 적습니다. 문장을 다듬어 놓은 문단을 나중에 통째로 지우게 될 수도 있기 때문입니다. 퇴고 점검표 단계 · 점검할 것 글 전체 · 제목이 내용을 대표하는가 / 서론의 목적과 결론의 답이","keywords":["참고문헌","퇴고"],"ref":{"tab":"concepts","idx":5},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-09","grade":"u"},
{"id":"kor-u-write-09#t0","kind":"term","title":"학술 보고서","text":"조사·실험·독서로 얻은 결과를 정해진 형식에 따라 객관적으로 정리해 알리는 글입니다. 출처와 방법을 밝혀 다른 사람이 확인할 수 있게 합니다.","keywords":["학술 보고서"],"ref":{"tab":"terms","idx":0},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-09","grade":"u"},
{"id":"kor-u-write-09#t1","kind":"term","title":"요약 보고서","text":"정해진 글의 핵심 주장과 근거를 줄여 정리한 보고서입니다. 자기 평가는 넣지 않거나 최소로 합니다.","keywords":["요약 보고서"],"ref":{"tab":"terms","idx":1},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-09","grade":"u"},
{"id":"kor-u-write-09#t2","kind":"term","title":"비평 보고서","text":"글·작품·이론을 요약한 뒤 기준을 세워 그 가치나 타당성을 평가하는 보고서입니다.","keywords":["비평 보고서"],"ref":{"tab":"terms","idx":2},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-09","grade":"u"},
{"id":"kor-u-write-09#t3","kind":"term","title":"조사 보고서","text":"설문·면담·관찰·문헌 조사로 자료를 모으고 분석한 결과를 정리한 보고서입니다.","keywords":["조사 보고서"],"ref":{"tab":"terms","idx":3},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-09","grade":"u"},
{"id":"kor-u-write-09#t4","kind":"term","title":"실험 보고서","text":"목적을 세우고 조건을 바꿔 가며 실험·측정한 과정과 결과, 고찰을 기록한 보고서입니다.","keywords":["실험 보고서"],"ref":{"tab":"terms","idx":4},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-09","grade":"u"},
{"id":"kor-u-write-09#t5","kind":"term","title":"초록","text":"보고서나 논문의 목적·방법·결과·결론을 한 문단 정도로 압축해 맨 앞에 두는 요약입니다.","keywords":["초록"],"ref":{"tab":"terms","idx":5},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-09","grade":"u"},
{"id":"kor-u-write-09#t6","kind":"term","title":"고찰","text":"실험 보고서에서 결과가 왜 그렇게 나왔는지 해석하고, 예상과의 차이나 오차의 원인을 따지는 부분입니다.","keywords":["고찰"],"ref":{"tab":"terms","idx":6},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-09","grade":"u"},
{"id":"kor-u-write-09#t7","kind":"term","title":"참고문헌","text":"보고서에서 인용하거나 참고한 자료를 정해진 형식에 따라 모아 적은 목록입니다. 본문의 인용과 하나하나 맞아야 합니다.","keywords":["참고문헌"],"ref":{"tab":"terms","idx":7},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-09","grade":"u"},
{"id":"kor-u-write-09#t8","kind":"term","title":"부록","text":"설문지 원본, 원자료처럼 본문에 다 넣기 어렵지만 확인에 필요한 자료를 보고서 뒤에 덧붙인 것입니다.","keywords":["부록"],"ref":{"tab":"terms","idx":8},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-09","grade":"u"},
{"id":"kor-u-write-09#t9","kind":"term","title":"퇴고","text":"다 쓴 글을 다시 읽으며 고치는 일입니다. 글 전체 → 문단 → 문장 → 표기 순서로 큰 것부터 점검합니다.","keywords":["퇴고"],"ref":{"tab":"terms","idx":9},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-09","grade":"u"},
{"id":"kor-u-write-09#f0","kind":"faq","title":"보고서랑 논문은 뭐가 달라요?","text":"둘 다 근거와 출처를 밝히는 학술적 글이라는 점은 같습니다. 보고서는 주로 수업 과제로, 정해진 주제에 대해 조사·실험·독서한 결과를 정리하는 데 무게가 있습니다. 논문은 학계에 새로운 지식을 더하는 것이 목적이라 앞선 연구를 폭넓게 검토하고, 독창적인 연구 문제와 엄격한 방법을 요구합니다. 보고서를 잘 쓰는 연습이 곧 논문 쓰기의 기초가 됩니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-09","grade":"u"},
{"id":"kor-u-write-09#f1","kind":"faq","title":"서론을 맨 처음에 써야 하나요?","text":"읽는 순서와 쓰는 순서가 같을 필요는 없습니다. 연구 목적을 짧게 적어 둔 뒤 본론부터 쓰고, 서론과 초록은 마지막에 다듬는 사람이 많습니다. 본론을 쓰다 보면 처음 생각과 초점이 달라지기 때문입니다. 다만 다 쓴 뒤에는 서론의 목적과 결론의 답이 맞는지 꼭 확인합니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-09","grade":"u"},
{"id":"kor-u-write-09#f2","kind":"faq","title":"표가 하나뿐이어도 번호를 붙여야 하나요?","text":"대부분의 양식에서는 하나뿐이어도 \"표 1\"처럼 번호를 붙입니다. 번호가 있어야 본문에서 \"표 1에서 보듯\"처럼 정확히 가리킬 수 있습니다. 과목에서 따로 정한 양식이 있으면 그것을 따릅니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-09","grade":"u"},
{"id":"kor-u-write-09#f3","kind":"faq","title":"결론에 제 생각을 써도 되나요?","text":"근거에 기댄 해석과 제언은 써도 되고, 써야 합니다. 결과가 어떤 의미가 있는지, 앞으로 무엇을 더 연구해야 하는지가 바로 글쓴이의 생각입니다. 다만 본론의 근거와 상관없는 감상(\"뜻깊었다\")이나 다짐, 결과보다 넓은 단정은 피합니다.","keywords":[],"ref":{"tab":"faq","idx":3},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-09","grade":"u"},
{"id":"kor-u-write-09#m0","kind":"mistake","title":"자주 하는 실수","text":"서론을 \"현대 사회에서 ○○은 매우 중요하다\" 같은 일반론으로만 채우는 실수 — 무엇이 아직 밝혀지지 않았는지(문제 제기)와 이 보고서가 무엇을 밝히려는지(연구 목적)를 구체적으로 씁니다.","keywords":[],"ref":{"tab":"faq"},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-09","grade":"u"},
{"id":"kor-u-write-09#m1","kind":"mistake","title":"자주 하는 실수","text":"표·그림에 번호·제목·출처를 빠뜨리거나, 본문에서 한 번도 언급하지 않고 붙여 두기만 하는 실수 — 본문에서 먼저 가리키고 핵심을 해석합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-09","grade":"u"},
{"id":"kor-u-write-09#m2","kind":"mistake","title":"자주 하는 실수","text":"결론에서 새 자료를 꺼내거나 조사 범위보다 넓게 일반화하는 실수 — 결론은 본론의 결과를 요약하고 의의·한계·제언을 밝히는 자리입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-09","grade":"u"},
{"id":"kor-u-write-10","kind":"unit","title":"학술 발표와 질의응답","text":"보고서 내용을 발표 자료로 구성하고, 시간에 맞춰 발표하며 질문과 토론에 침착하게 답하는 법을 익힙니다. 한 장에 한 메시지를 담아 발표 자료를 구성할 수 있다. 발표를 도입·본론·마무리로 짜고 정해진 시간에 맞게 배분할 수 있다. 핵심 반복과 전환 표현으로 청중이 따라오기 쉽게 말할 수 있다. 질문에 정확하고 예의 있게 답하고, 학술 토론의 예절을 지킬…","keywords":["한 장에 한 메시지","메시지 제목","시간 배분","리허설","전환 표현","핵심 반복","질의응답","예상 질문","좌장"],"ref":{"tab":"concepts","idx":0},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-10","grade":"u"},
{"id":"kor-u-write-10#c0","kind":"concept","title":"발표 자료 구성: 한 장에 한 메시지","text":"보고서는 독자가 자기 속도로 되돌아가며 읽지만, 발표는 청중이 발표자의 속도로 한 번 듣고 지나갑니다. 그래서 발표 자료는 보고서를 옮겨 붙인 것이 아니라 청중이 한눈에 알아보도록 다시 짠 것이어야 합니다. 가장 중요한 원칙은 한 장에 한 메시지입니다. 제목을 문장으로: \"결과\" 같은 ","keywords":["한 장에 한 메시지"],"ref":{"tab":"concepts","idx":0},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-10","grade":"u"},
{"id":"kor-u-write-10#c1","kind":"concept","title":"발표의 짜임과 시간 배분","text":"학술 발표도 보고서처럼 도입 – 본론 – 마무리로 짭니다. 부분 · 할 일 도입 · 주의 끌기, 주제와 목적, 발표 순서 예고 본론 · 배경·방법·결과·논의. 핵심은 두세 가지로 마무리 · 핵심 요약, 의의와 한계, 질문 받기 시간 배분은 정해진 시간에서 거꾸로 계산합니다. 질의응답 시","keywords":["시간 배분","리허설","질의응답"],"ref":{"tab":"concepts","idx":1},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-10","grade":"u"},
{"id":"kor-u-write-10#c2","kind":"concept","title":"말하기 전략: 핵심 반복과 전환 표현","text":"읽는 사람은 놓친 문장을 다시 읽을 수 있지만, 듣는 사람은 그럴 수 없습니다. 그래서 발표에서는 글보다 반복과 길잡이 말이 더 필요합니다. 핵심 반복: 핵심 메시지를 도입에서 예고하고, 본론에서 근거와 함께 펼치고, 마무리에서 다시 요약합니다. 글에서는 군더더기일 반복이 발표에서는 청","keywords":["전환 표현","핵심 반복"],"ref":{"tab":"concepts","idx":2},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-10","grade":"u"},
{"id":"kor-u-write-10#c3","kind":"concept","title":"질의응답: 질문에 답하는 법","text":"질의응답은 발표의 덤이 아니라 발표의 일부입니다. 청중이 무엇을 궁금해하는지 알고, 발표를 보완할 기회입니다. 끝까지 듣는다: 질문 도중에 끼어들지 않고, 필요하면 메모합니다. 확인한다: 길거나 복잡한 질문은 \"○○에 대해 물으신 것으로 이해했습니다\"처럼 요지를 되짚습니다. 오해를 막고","keywords":["질의응답","예상 질문"],"ref":{"tab":"concepts","idx":3},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-10","grade":"u"},
{"id":"kor-u-write-10#c4","kind":"concept","title":"학술 토론 예절","text":"질의응답과 토론은 발표자와 청중이 함께 지식을 다듬는 자리입니다. 질문하는 쪽과 답하는 쪽 모두 지켜야 할 예절이 있습니다. 질문하는 쪽 요지를 밝혀 짧고 분명하게, 한 번에 한두 개만 묻습니다. 자기 연구를 길게 소개하는 자리가 아닙니다. 사람이 아니라 내용(주장·근거·방법)을 겨눕니","keywords":["질의응답"],"ref":{"tab":"concepts","idx":4},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-10","grade":"u"},
{"id":"kor-u-write-10#t0","kind":"term","title":"한 장에 한 메시지","text":"발표 자료 한 장에는 전하려는 핵심을 하나만 담는다는 원칙입니다. 제목을 그 핵심을 담은 문장으로 쓰면 지키기 쉽습니다.","keywords":["한 장에 한 메시지"],"ref":{"tab":"terms","idx":0},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-10","grade":"u"},
{"id":"kor-u-write-10#t1","kind":"term","title":"메시지 제목","text":"\"결과\" 같은 낱말 대신 \"계획표를 쓴 학생이 과제를 먼저 냈다\"처럼 그 장의 핵심을 문장으로 쓴 슬라이드 제목입니다.","keywords":["메시지 제목"],"ref":{"tab":"terms","idx":1},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-10","grade":"u"},
{"id":"kor-u-write-10#t2","kind":"term","title":"시간 배분","text":"정해진 발표 시간을 도입·본론·마무리(와 질의응답)에 나누어 정하는 일입니다. 질의응답처럼 고정된 시간을 먼저 빼고 계산합니다.","keywords":["시간 배분"],"ref":{"tab":"terms","idx":2},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-10","grade":"u"},
{"id":"kor-u-write-10#t3","kind":"term","title":"리허설","text":"실제 발표처럼 소리 내어 미리 해 보는 연습입니다. 시간을 재고, 막히는 곳과 넘치는 곳을 찾습니다.","keywords":["리허설"],"ref":{"tab":"terms","idx":3},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-10","grade":"u"},
{"id":"kor-u-write-10#t4","kind":"term","title":"전환 표현","text":"청중에게 발표의 흐름을 알려 주는 길잡이 말입니다. 예고(\"세 부분으로 말씀드리겠습니다\"), 전환(\"이제 방법으로 넘어가겠습니다\"), 강조, 요약 등이 있습니다.","keywords":["전환 표현"],"ref":{"tab":"terms","idx":4},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-10","grade":"u"},
{"id":"kor-u-write-10#t5","kind":"term","title":"핵심 반복","text":"핵심 메시지를 도입에서 예고하고, 본론에서 펼치고, 마무리에서 요약하여 되풀이하는 말하기 전략입니다.","keywords":["핵심 반복"],"ref":{"tab":"terms","idx":5},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-10","grade":"u"},
{"id":"kor-u-write-10#t6","kind":"term","title":"질의응답","text":"발표 뒤에 청중이 묻고 발표자가 답하는 시간입니다. 요지 확인 → 결론부터 짧게 → 근거 순서로 답합니다.","keywords":["질의응답"],"ref":{"tab":"terms","idx":6},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-10","grade":"u"},
{"id":"kor-u-write-10#t7","kind":"term","title":"예상 질문","text":"발표를 준비하며 청중이 물을 법한 질문을 미리 적어 본 것입니다. 답에 필요한 자료는 보충 슬라이드로 마련해 둡니다.","keywords":["예상 질문"],"ref":{"tab":"terms","idx":7},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-10","grade":"u"},
{"id":"kor-u-write-10#t8","kind":"term","title":"좌장","text":"학술 발표회에서 발표 순서와 시간을 관리하고 질의응답을 진행하는 사회자입니다.","keywords":["좌장"],"ref":{"tab":"terms","idx":8},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-10","grade":"u"},
{"id":"kor-u-write-10#f0","kind":"faq","title":"떨려서 말이 자꾸 빨라져요. 어떻게 해요?","text":"첫 1분을 거의 외울 만큼 연습해 두면 시작의 긴장이 크게 줄어듭니다. 슬라이드마다 \"여기서 쉰다\"는 표시를 대본에 해 두고, 핵심 수치는 일부러 천천히 말하십시오. 리허설을 녹음해 들어 보면 어디서 빨라지는지 알 수 있습니다. 조금 떨리는 것은 청중도 이해하니, 내용을 정확히 전하는 데 집중하면 됩니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-10","grade":"u"},
{"id":"kor-u-write-10#f1","kind":"faq","title":"대본을 보고 읽어도 되나요?","text":"대본을 그대로 읽으면 시선이 청중에게 가지 못하고 말투가 딱딱해집니다. 대본은 연습 때 쓰고, 발표 때는 핵심어 메모나 슬라이드 제목을 길잡이로 삼는 것이 좋습니다. 다만 정확해야 하는 수치나 인용은 메모를 보고 말해도 괜찮습니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-10","grade":"u"},
{"id":"kor-u-write-10#f2","kind":"faq","title":"질문이 하나도 안 나오면 실패한 건가요?","text":"그렇지 않습니다. 시간이 부족했거나 청중이 아직 내용을 정리하는 중일 수 있습니다. 발표자가 먼저 \"이번 조사의 한계에 대해 더 말씀드리면 …\"처럼 보충 내용을 짧게 덧붙이거나, 좌장의 진행을 따르면 됩니다. 발표 뒤에 따로 질문하러 오는 사람도 많습니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-10","grade":"u"},
{"id":"kor-u-write-10#f3","kind":"faq","title":"날카로운 질문을 받으면 머리가 하얘져요.","text":"먼저 질문의 요지를 되짚으며 시간을 버십시오. \"○○에 대해 물으신 것으로 이해했습니다.\" 그동안 답을 정리할 수 있습니다. 날카로운 질문은 대개 사람이 아니라 내용을 겨눈 것이니, 맞는 지적이면 한계로 인정하고 아니면 근거로 설명하면 됩니다. 예상 질문을 미리 적어 연습해 두면 크게 도움이 됩니다.","keywords":[],"ref":{"tab":"faq","idx":3},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-10","grade":"u"},
{"id":"kor-u-write-10#m0","kind":"mistake","title":"자주 하는 실수","text":"보고서 문단을 그대로 슬라이드에 옮기고 화면을 읽기만 하는 실수 — 한 장에 한 메시지, 제목은 핵심 문장, 글은 핵심어만 둡니다.","keywords":[],"ref":{"tab":"faq"},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-10","grade":"u"},
{"id":"kor-u-write-10#m1","kind":"mistake","title":"자주 하는 실수","text":"질의응답 시간을 빼지 않고 시간을 배분해 발표가 넘치는 실수 — 고정된 시간을 먼저 빼고, 리허설로 실제 시간을 재 봅니다.","keywords":[],"ref":{"tab":"faq"},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-10","grade":"u"},
{"id":"kor-u-write-10#m2","kind":"mistake","title":"자주 하는 실수","text":"모르는 질문에 짐작으로 답하거나, 날카로운 질문에 감정적으로 맞서는 실수 — 모르면 인정하고, 비판에는 내용으로 답합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"kor","course":"kor-u-write","unit":"kor-u-write-10","grade":"u"}
]);
